# Förderwerbende Personen, höhere Gewalt, Kontrollen, Sanktionen, Aufbewahrung und Auszahlung (o6_21).
package oepul.o6_21.administration

import data.oepul.o6_21.lib

mi := lib.measure_input

applicant := object.get(input, ["farm", "applicant"], {})

# --- Förderwerbende Personen (SRL 1.4, ATB 5.2) -------------------------------------------------

applicant_type_row := row if {
	some row in lib.tables.applicant_types
	row.person_type == applicant.person_type
}

# O6_21-APPL-01: zulässige Rechtsformen; juristische Personen/Personenvereinigungen nur bis 25 % Beteiligung
# von Gebietskörperschaften.
applicant_issue("person_type_not_eligible") if not applicant_type_row

applicant_issue("public_body_share_above_25_percent") if {
	applicant_type_row.max_public_body_share_percent != null
	object.get(applicant, "public_body_share_percent", 0) > applicant_type_row.max_public_body_share_percent
}

# O6_21-APPL-02: Gebietskörperschaften sind bei dieser Maßnahme ausgeschlossen (keine Ausnahme für Maßnahme 21).
applicant_issue("public_body_excluded") if {
	object.get(applicant, "is_public_body", false)
	not public_body_exception_for_measure
}

public_body_exception_for_measure if {
	some m in lib.tables.public_body_eligible_measures
	m.srl_number == "21"
}

# O6_21-APPL-03: aktiver Landwirt, landwirtschaftliche Tätigkeit, Betrieb im eigenen Namen und auf eigene Rechnung.
applicant_issue("not_active_farmer") if not object.get(applicant, "is_active_farmer", false)

applicant_issue("farm_not_managed_in_own_name") if {
	not object.get(applicant, "manages_farm_in_own_name_and_account", false)
}

applicant_issues := {code |
	some code in {
		"person_type_not_eligible",
		"public_body_share_above_25_percent",
		"public_body_excluded",
		"not_active_farmer",
		"farm_not_managed_in_own_name",
	}
	applicant_issue(code)
}

# --- Höhere Gewalt (GSP-AV § 6, § 7) -------------------------------------------------------------

# O6_21-FM-01: Geltendmachung binnen drei Wochen ab dem Zeitpunkt, ab dem dies möglich ist, mit Unterlagen.
recognised_force_majeure_events contains ev.event_id if {
	some ev in object.get(mi, "force_majeure_events", [])
	ev.reported_on != null
	lib.days_between(ev.able_to_report_from, ev.reported_on) <= lib.deadlines.force_majeure_notification_days
	ev.documented
}

late_force_majeure_events contains ev.event_id if {
	some ev in object.get(mi, "force_majeure_events", [])
	ev.reported_on != null
	lib.days_between(ev.able_to_report_from, ev.reported_on) > lib.deadlines.force_majeure_notification_days
}

# O6_21-FM-03: natürliche Umstände (z. B. Tod durch Krankheit/Unfall) – keine Verwaltungssanktion bei
# schriftlicher Meldung binnen drei Wochen nach Feststellung der Reduzierung.
natural_circumstance_sanction_waived contains ev.event_id if {
	some ev in object.get(mi, "natural_circumstance_events", [])
	lib.days_between(ev.reduction_found_on, ev.reported_on) <= lib.deadlines.natural_circumstances_notification_days
}

# --- Kontrollen (SRL 1.11) -------------------------------------------------------------------------

# O6_21-CTRL-01: Verweigerung/Verhinderung der Vor-Ort-Kontrolle (ohne höhere Gewalt) führt zur Ablehnung,
# keine Prämie im laufenden Jahr, Beendigung und Rückabwicklung der Verträge.
control_refused if {
	object.get(mi, "control_refused", false)
	not object.get(mi, "control_refusal_due_to_force_majeure", false)
}

# --- Sanktionen (SRL 1.12, GSP-AV § 48, ATB 8.2) -------------------------------------------------

stage_row(stage) := row if {
	some row in lib.tables.sanction_stages
	row.stage == stage
}

# O6_21-SANC-02: ab 2027 statt Verwarnung Einbehalt von 1 % der Maßnahmenprämie.
stage_percent(stage) := lib.tables.sanction_rules.warning_withholding_percent_from_2027 if {
	stage == 1
	lib.year >= lib.tables.sanction_rules.warning_replaced_from_year
}

stage_percent(stage) := stage_row(stage).reduction_percent if {
	stage != 1
}

stage_percent(stage) := 0 if {
	stage == 1
	lib.year < lib.tables.sanction_rules.warning_replaced_from_year
}

violation_stages := object.get(mi, "content_violation_stages", [])

# O6_21-SANC-01: Kumulation durch Addition der Prozentsätze, Obergrenze 100 % der Jahresprämie.
content_reduction_percent := min([lib.tables.sanction_rules.max_cumulated_reduction_percent, sum([stage_percent(s) | some s in violation_stages])])

# O6_21-SANC-03: zweimalige 100 %-Kürzung im Vertragszeitraum → Ausschluss und Rückforderung.
full_reductions_total := object.get(mi, "previous_full_reductions_in_period", 0) + count([1 | content_reduction_percent == 100])

exclusion_from_measure if full_reductions_total >= lib.tables.sanction_rules.full_reductions_for_exclusion

# --- Aufbewahrung, Auszahlung (GSP-AV § 16, § 52; SRL 1.10.7) -------------------------------------

# O6_21-REC-01: Aufbewahrung vier Jahre vom Ende des Kalenderjahres, auf das sich die Zahlungen beziehen.
records_retention_until := sprintf("%d-12-31", [lib.year + lib.deadlines.record_retention_years_after_year_end])

# O6_21-PAY-03: Auszahlung bis 30. Juni des Folgejahres, Zahlungen nicht vor dem 1. Dezember des Antragsjahres.
payment_window := {
	"not_before": sprintf("%d-%s", [lib.year, lib.tables.payment.payments_not_before_month_day_application_year]),
	"until": sprintf("%d-%s", [lib.year + 1, lib.tables.payment.payment_deadline_month_day_following_year]),
}

# O6_21-PAY-04: Vorauszahlung max. 75 % nach Abschluss der Verwaltungskontrolle.
max_advance_payment(amount) := lib.r2(amount * lib.tables.payment.advance_payment_max_share)

# O6_21-REC-02: Betriebsübertragung binnen vier Wochen ab Wirksamkeit anzuzeigen.
farm_transfer_notification_late if {
	t := object.get(mi, "farm_transfer", null)
	t != null
	lib.days_between(t.effective_on, t.notified_on) > lib.deadlines.farm_transfer_notification_days
}

# O6_21-PAY-05: Rückforderung binnen vier Wochen; Absehen von Wiedereinziehung bis 100 € (Zinsen allein bis 50 €).
recovery_may_be_waived(amount, interest_only) if {
	not interest_only
	amount <= lib.tables.payment.recovery_waiver_max_eur
}

recovery_may_be_waived(amount, interest_only) if {
	interest_only
	amount <= lib.tables.payment.recovery_waiver_interest_only_max_eur
}

# Teilnahmefähige Tiere, Einhaltung der Haltungsbedingungen je Tier, Abmeldungen und RGVE (o6_21).
package oepul.o6_21.animals

import data.oepul.o6_21.application
import data.oepul.o6_21.housing
import data.oepul.o6_21.lib

mi := lib.measure_input

animals := housing.animals

deregistrations := object.get(mi, "deregistered_animals", [])

deregistered_tags contains d.ear_tag if {
	some d in deregistrations
}

# --- Teilnahme je Tier und Kategorie ------------------------------------------------------------

# O6_21-ELIG-03 / O6_21-CAT-01: Teilnahme mit Rindern der beantragten Kategorien gemäß RGVE-Schlüssel.
participating_categories(a) := {cat_id |
	some cat_id in application.valid_categories
	lib.animal_in_category(a, cat_id)
	not milk_delivery_excluded(cat_id)
	lib.category_days(a, cat_id) > 0
}

# O6_21-ELIG-04: Betriebe mit Milchanlieferung (auch saisonal auf der Alm) sind von der Kategorie
# weibliche Rinder ab ½ bis unter 2 Jahre ausgeschlossen.
milk_delivery_excluded(cat_id) if {
	lib.category_def(cat_id).excluded_with_milk_delivery
	milk_delivery
}

milk_delivery if object.get(input, ["farm", "dairy", "milk_delivery_to_dairy"], false)

milk_delivery if object.get(input, ["farm", "dairy", "seasonal_alpine_milk_delivery"], false)

participation_intervals(a) := [iv |
	some cat_id in participating_categories(a)
	some band in lib.category_def(cat_id).age_bands
	lib.band_days(a, band) > 0
	iv := [
		max([lib.presence_start_ns(a), lib.age_band_interval(a, band)[0]]),
		min([lib.presence_end_ns(a), lib.age_band_interval(a, band)[1]]),
	]
]

period_overlaps_participation(a, p) if {
	some iv in participation_intervals(a)
	lib.overlap_days(lib.parse_date(p.start), lib.parse_date(p.end), iv[0], iv[1]) > 0
}

# --- Einhaltung je Tier ---------------------------------------------------------------------------

# O6_21-GROUP-02: Einzelhaltung kranker/verletzter Tiere max. 10 Tage, eingestreut, dokumentiert.
individual_period_days(p) := lib.days_between(p.start, p.end) + 1

animal_issue(a, "tethering") if {
	some p in object.get(a, "tethering_periods", [])
	period_overlaps_participation(a, p)
}

animal_issue(a, "full_slatted_floor") if {
	some p in object.get(a, "full_slatted_periods", [])
	period_overlaps_participation(a, p)
}

animal_issue(a, "sick_separation_over_10_days") if {
	some p in object.get(a, "individual_housing_periods", [])
	p.reason in {"illness", "injury"}
	period_overlaps_participation(a, p)
	individual_period_days(p) > lib.thresholds.max_individual_housing_days_sick_or_injured
}

animal_issue(a, "individual_housing_not_bedded") if {
	some p in object.get(a, "individual_housing_periods", [])
	period_overlaps_participation(a, p)
	not object.get(p, "bedded", false)
}

# O6_21-GROUP-03: Kälber unter 21 Tagen dürfen einzeln auf eingestreutem System mit Sozialkontakt gehalten werden.
animal_issue(a, "calf_individual_housing_too_old") if {
	some p in object.get(a, "individual_housing_periods", [])
	p.reason == "calf_under_21_days"
	period_overlaps_participation(a, p)
	lib.age_days_at(a, p.end) >= lib.thresholds.calf_individual_housing_max_age_days_exclusive
}

animal_issue(a, "calf_individual_housing_without_social_contact") if {
	some p in object.get(a, "individual_housing_periods", [])
	p.reason == "calf_under_21_days"
	period_overlaps_participation(a, p)
	not object.get(p, "social_contact", false)
}

animal_issue(a, "individual_housing_not_permitted") if {
	some p in object.get(a, "individual_housing_periods", [])
	not p.reason in {"illness", "injury", "calf_under_21_days"}
	period_overlaps_participation(a, p)
}

animal_issue(a, "compartment_noncompliant") if {
	count(participation_intervals(a)) > 0
	object.get(a, "stall_compartment_id", null) in housing.noncompliant_compartments
}

# O6_21-COMB-02: Tiere in ganzjähriger Freilandhaltung ohne entsprechendes Stallsystem sind nicht förderfähig.
animal_issue(a, "no_stall_year_round_outdoor") if {
	object.get(a, "year_round_outdoor_without_stall", false)
}

animal_issue(a, "no_stall_assigned") if {
	count(participation_intervals(a)) > 0
	not object.get(a, "year_round_outdoor_without_stall", false)
	object.get(a, "stall_compartment_id", null) == null
}

# Dokumentationspflicht (kein Förderausschluss, aber Verstoß gegen Förderverpflichtung).
documentation_issue(a, "individual_housing_not_documented") if {
	some p in object.get(a, "individual_housing_periods", [])
	p.reason in {"illness", "injury"}
	period_overlaps_participation(a, p)
	not object.get(p, "documented", false)
}

issues_of(a) := {code | some code in issue_codes; animal_issue(a, code)}

issue_codes := {
	"tethering",
	"full_slatted_floor",
	"sick_separation_over_10_days",
	"individual_housing_not_bedded",
	"calf_individual_housing_too_old",
	"calf_individual_housing_without_social_contact",
	"individual_housing_not_permitted",
	"compartment_noncompliant",
	"no_stall_year_round_outdoor",
	"no_stall_assigned",
}

# GSP-AV § 6 Abs. 4 Z 1: bei anerkannter höherer Gewalt bleibt der Anspruch für die zum Zeitpunkt
# des Eintretens förderfähigen Tiere bestehen.
force_majeure_excused(a) if {
	ev_id := object.get(a, "noncompliance_force_majeure_event_id", null)
	ev_id != null
	ev_id in data.oepul.o6_21.administration.recognised_force_majeure_events
}

noncompliant(a) if {
	count(issues_of(a)) > 0
	not force_majeure_excused(a)
}

# --- Abmeldepflicht (Kapitel 6.5) ----------------------------------------------------------------

# O6_21-REP-01: gesonderte Meldepflicht, wenn die Stallhaltung für einzelne Tiere nicht einhaltbar ist
# und die Tiere am Betrieb verbleiben.
deregistration_required contains a.ear_tag if {
	some a in animals
	noncompliant(a)
	count(participation_intervals(a)) > 0
}

# Verstoß: nicht eingehaltene Haltungsbedingungen ohne Abmeldung.
missing_deregistrations contains tag if {
	some tag in deregistration_required
	not tag in deregistered_tags
}

# --- Ermittlung der Tiere (GSP-AV § 43) --------------------------------------------------------

# O6_21-CTRL-03: Rinder gelten nur als ermittelt, wenn sie aus der Rinderdatenbank ermittelt werden;
# bei Kontrollen nicht vorgefundene Tiere werden nicht berücksichtigt.
determined(a) if {
	object.get(a, "registered_in_cattle_database", true)
	object.get(a, "determined_at_control", true) != false
}

# O6_21-ELIG-02: geförderte Tiere müssen in Österreich gehalten werden.
kept_in_austria(a) if object.get(a, "kept_in_austria", true)

# Prämienfähig: teilnehmende Kategorie, nicht abgemeldet (O6_21-REP-02 Abmeldung = ganzjährig keine Prämie
# in allen Kategorien), Haltungsbedingungen eingehalten, ermittelt, in Österreich gehalten.
premium_eligible(a) if {
	count(participating_categories(a)) > 0
	not a.ear_tag in deregistered_tags
	not noncompliant(a)
	determined(a)
	kept_in_austria(a)
}

eligible_flag(a) if premium_eligible(a)

eligible_flag(a) := false if not premium_eligible(a)

# --- RGVE (Kapitel 9 und 10) ---------------------------------------------------------------------

# O6_21-RGVE-01/02: anteilige RGVE je Tier über die teilnehmenden Kategorien (taggenau, Jahresdurchschnitt).
animal_rgve(a) := sum([lib.category_rgve(a, cat_id) | some cat_id in participating_categories(a)])

eligible_animal_rgve[a.ear_tag] := lib.r4(animal_rgve(a)) if {
	some a in animals
	premium_eligible(a)
}

# Bruttowert aller Tiere in beantragten Kategorien (förderbare Rinder, vor Abmeldungen) – Basis für TGD-Schwelle.
gross_category_rgve := lib.r4(sum([animal_rgve(a) |
	some a in animals
	count(participating_categories(a)) > 0
	kept_in_austria(a)
]))

eligible_rgve := lib.r4(sum([v | some v in eligible_animal_rgve]))

rgve_by_category[cat_id] := lib.r4(total) if {
	some cat_id in application.valid_categories
	total := sum([lib.category_rgve(a, cat_id) |
		some a in animals
		premium_eligible(a)
		cat_id in participating_categories(a)
	])
}

# O6_21-APP-06: Kategorie ohne mindestens ein prämienfähiges Tier im Förderjahr erlischt automatisch.
categories_lapsing contains cat_id if {
	some cat_id in application.valid_categories
	count([a |
		some a in animals
		premium_eligible(a)
		cat_id in participating_categories(a)
	]) == 0
}

# O6_21-PREM-02: reduzierter Satz bei Alm, Tierwohl – Weide oder gekoppelter Stützung für Almrinder.
reduced_rate_animal(a) if object.get(a, "alpine_pasture_measure_premium", false)

reduced_rate_animal(a) if object.get(a, "pasture_measure_o6_20", false)

reduced_rate_animal(a) if object.get(a, "coupled_support_alpine", false)

animal_rate_id(a) := "reduced_overlap" if reduced_rate_animal(a)

animal_rate_id(a) := "standard" if not reduced_rate_animal(a)

animal_premium[a.ear_tag] := lib.r2(eligible_animal_rgve[a.ear_tag] * lib.rate(animal_rate_id(a), lib.year)) if {
	some a in animals
	premium_eligible(a)
}

animal_findings[a.ear_tag] := {
	"participating_categories": participating_categories(a),
	"issues": issues_of(a),
	"premium_eligible": eligible_flag(a),
	"deregistered": a.ear_tag in deregistered_tags,
} if {
	some a in animals
}

# Beantragung, Vertragszeitraum, Verlängerung, Ausstieg und Übernahme (o6_21).
package oepul.o6_21.application

import data.oepul.o6_21.lib

mi := lib.measure_input

year := lib.year

categories := object.get(mi, "categories", [])

exits := object.get(mi, "exits", [])

# O6_21-APP-01: Maßnahmenantrag bis spätestens 31.12. vor dem ersten Verpflichtungsjahr.
application_timely(entry) if {
	lib.parse_date(entry.applied_on) <= lib.year_end_ns(entry.first_year - 1)
}

# O6_21-APP-07: verspätete Wiederbeantragung nach Erlöschen nur mit Korrektur und gesondertem Ersuchen,
# wirksam nur bei Anerkennung durch die AMA.
application_timely(entry) if {
	object.get(entry, "late_reentry_correction_submitted", false)
	object.get(entry, "late_reentry_written_request_submitted", false)
	object.get(entry, "late_reentry_accepted", false)
}

# O6_21-APP-03: letzter Einstieg in Kategorien mit Förderjahr 2027.
within_last_entry_categories(entry) if {
	entry.first_year <= lib.deadlines.last_contract_start_year_categories
}

# O6_21-APP-04: letzter Einstieg in den optionalen Zuschlag mit Förderjahr 2028.
within_last_entry_supplement(entry) if {
	entry.first_year <= lib.deadlines.last_contract_start_year_supplement
}

not_lapsed(entry) if {
	object.get(entry, "lapsed_after_year", null) == null
}

not_lapsed(entry) if {
	lapsed := object.get(entry, "lapsed_after_year", null)
	lapsed != null
	year <= lapsed
}

# O6_21-EXIT-04: Ausstieg nur bis zur Ankündigung bzw. Durchführung einer Vor-Ort-Kontrolle
# oder Mitteilung des Ergebnisses einer Verwaltungskontrolle.
exit_effective(_) if {
	not mi.control_announced_on
}

exit_effective(e) if {
	lib.parse_date(e.declared_on) < lib.parse_date(mi.control_announced_on)
}

# O6_21-EXIT-02: Eine im Zeitraum 1.1.–31.12. durchgeführte Abmeldung macht die Maßnahme
# (bzw. Kategorie/Zuschlag) für dieses Förderjahr ungültig.
exited_scope_for(entry, _, _) if {
	some e in exits
	exit_effective(e)
	e.scope == "measure"
	lib.parse_date(e.declared_on) > lib.parse_date(entry.applied_on)
	lib.date_year(e.declared_on) <= year
}

exited_scope_for(entry, "category", cat_id) if {
	some e in exits
	exit_effective(e)
	e.scope == "category"
	e.category_id == cat_id
	lib.parse_date(e.declared_on) > lib.parse_date(entry.applied_on)
	lib.date_year(e.declared_on) <= year
}

exited_scope_for(entry, "supplement", _) if {
	some e in exits
	exit_effective(e)
	e.scope == "supplement"
	lib.parse_date(e.declared_on) > lib.parse_date(entry.applied_on)
	lib.date_year(e.declared_on) <= year
}

# Gültige Kategorie im Förderjahr (automatische Verlängerung, solange nicht abgemeldet oder erloschen).
category_valid(cat_id) if {
	some entry in categories
	entry.category_id == cat_id
	application_timely(entry)
	within_last_entry_categories(entry)
	entry.first_year <= year
	not_lapsed(entry)
	not exited_scope_for(entry, "category", cat_id)
}

valid_categories contains cat_id if {
	some c in lib.tables.animal_categories
	cat_id := c.category_id
	category_valid(cat_id)
}

applied_categories contains entry.category_id if {
	some entry in categories
}

late_or_invalid_category_applications contains entry.category_id if {
	some entry in categories
	not application_timely(entry)
}

category_applications_after_last_entry contains entry.category_id if {
	some entry in categories
	not within_last_entry_categories(entry)
}

supplement := object.get(mi, "composting_supplement", null)

supplement_valid if {
	supplement != null
	application_timely(supplement)
	within_last_entry_supplement(supplement)
	supplement.first_year <= year
	not_lapsed(supplement)
	not exited_scope_for(supplement, "supplement", null)
	count(valid_categories) > 0
}

# O6_21-APP-08: Ausstieg aus der Maßnahme erst nach Erfüllung des einjährigen Vertragszeitraumes;
# eine Abmeldung im laufenden Jahr bewirkt die Ungültigkeit für dieses Jahr.
exits_invalidating_current_year contains e if {
	some e in exits
	exit_effective(e)
	lib.date_year(e.declared_on) == year
}

exits_ineffective_after_control contains e if {
	some e in exits
	not exit_effective(e)
}

# O6_21-TAKE-01: Maßnahmenübernahme nur in Einzelfällen bei Betriebsauflösung, -teilung oder -zusammenlegung;
# Tiere und Flächen müssen vom selben Vorbetrieb stammen.
takeover := object.get(mi, "takeover", {"is_takeover": false})

takeover_allowed if {
	takeover.is_takeover
	some r in lib.tables.takeover_allowed_reasons
	r.reason == takeover.reason
	takeover.animals_and_areas_from_same_previous_holding
}

takeover_violation if {
	takeover.is_takeover
	not takeover_allowed
}

# O6_21-APP-01 / O6_21-CONTRACT-01: Vertragsjahr ist das Kalenderjahr.
commitment_period := {
	"from": sprintf("%d-01-01", [year]),
	"to": sprintf("%d-12-31", [year]),
}

# O6_21-APP-05: Ersetzte (ausgelaufene) Kategorien bleiben ohne Abmeldung nach dem 31.12. gültig
# und müssen weiterhin eingehalten werden.
replaced_categories_still_binding contains entry.category_id if {
	some entry in categories
	object.get(entry, "replaced_by_category_id", null) != null
	category_valid(entry.category_id)
}

# Optionaler Zuschlag Festmistkompostierung (o6_21, Kapitel 6.4; SRL 2.21; NAPV § 6).
package oepul.o6_21.composting

import data.oepul.o6_21.application
import data.oepul.o6_21.lib

cfg := lib.tables.composting

comp := object.get(input, ["livestock", "solid_manure_composting"], {})

windrows := object.get(comp, "windrows", [])

equipment_row(equip) := row if {
	some row in lib.tables.turning_equipment
	row.equipment == equip
}

# O6_21-COMP-03: Frontlader zählt nicht als Umsetzen; Miststreuer/adäquate Geräte nur bei vollständigem Umsetzen.
counting_turning(t) if {
	row := equipment_row(t.equipment)
	row.counts_for_turning
	not row.requires_complete_turning
}

counting_turning(t) if {
	row := equipment_row(t.equipment)
	row.counts_for_turning
	row.requires_complete_turning
	object.get(t, "windrow_completely_turned", false)
}

counting_turning_dates(w) := sort([t.date |
	some t in object.get(w, "turnings", [])
	counting_turning(t)
])

# O6_21-COMP-02: mindestens zweimaliges Umsetzen im Abstand von mindestens 14 Tagen.
turning_requirement_met(w) if {
	dates := counting_turning_dates(w)
	count(dates) >= cfg.min_turnings
	some i, j
	i < j
	lib.days_between(dates[i], dates[j]) >= cfg.min_turning_interval_days
}

# O6_21-COMP-04: Kompostwender am Betrieb vorhanden oder überbetrieblicher Einsatz belegt.
turner_available if comp.compost_turner_on_farm

turner_available if comp.external_turner_use_documented

turner_used(w) if {
	some t in object.get(w, "turnings", [])
	t.equipment == "compost_turner"
}

turner_availability_ok(w) if not turner_used(w)

turner_availability_ok(w) if {
	turner_used(w)
	turner_available
}

# O6_21-COMP-02: Standardmiete mit Umsetzen.
windrow_method_ok(w) if {
	w.method == "turned"
	turning_requirement_met(w)
	turner_availability_ok(w)
}

# O6_21-COMP-05: ab Antragsjahr 2025 Mischung/Schichtung aus Festmist und Material der Feldproduktion
# bzw. Strauch-/Astschnitt; kein Umsetzen erforderlich.
windrow_method_ok(w) if {
	w.method == "mixed_or_layered"
	lib.year >= cfg.mixed_windrows_from_year
	some m in object.get(w, "plant_materials", [])
	some row in lib.tables.mixed_windrow_plant_materials
	row.material == m
}

# O6_21-COMP-06: wendefreie Kompostierung – Beimengung organischen Materials in nennenswertem Ausmaß,
# Kompostierungsverfahren; strohreicher Mist allein genügt nicht.
windrow_method_ok(w) if {
	w.method == "turning_free_with_added_material"
	object.get(w, "added_material_significant", false)
	object.get(w, "composting_process", null) != null
	not object.get(w, "straw_rich_manure_only", false)
}

# O6_21-COMP-08: NAPV – Lagerung zur Kompostierung auf unbefestigten Flächen nur bei abgedeckter Miete
# und Einhaltung von § 6 Abs. 7 Z 2, 4, 5 und 6.
napv_ok(w) if not object.get(w, "on_unpaved_area", false)

napv_ok(w) if {
	w.on_unpaved_area
	w.covered
	w.distance_to_surface_water_m >= 25
	not w.risk_of_seepage_to_water
	not w.waterlogged_soil
	w.groundwater_depth_m > 1
}

# O6_21-COMP-07: Dokumentation von Anlage und Umsetzen der Kompostmiete.
windrow_documented(w) if {
	w.documented_set_up
	w.method != "turned"
}

windrow_documented(w) if {
	w.documented_set_up
	w.method == "turned"
	w.documented_turnings
}

windrow_violations[w.windrow_id] := v if {
	some w in windrows
	v := {code | some code in windrow_codes; windrow_failed(w, code)}
}

windrow_codes := {"method_not_met", "napv_storage_not_met", "documentation_missing"}

windrow_failed(w, "method_not_met") if not windrow_method_ok(w)

windrow_failed(w, "napv_storage_not_met") if not napv_ok(w)

windrow_failed(w, "documentation_missing") if not windrow_documented(w)

supplement_codes := {
	"not_all_solid_manure_composted",
	"compost_barn",
	"no_windrows",
	"windrow_noncompliant",
	"application_or_transfer_not_documented",
}

# O6_21-COMP-01: gesamter am Betrieb anfallender Festmist (unabhängig von der Tierart) zu Kompostmieten am Betrieb.
supplement_failed("not_all_solid_manure_composted") if not comp.all_solid_manure_composted_on_farm

# O6_21-COMP-09: Kompostställe erhalten keinen Zuschlag.
supplement_failed("compost_barn") if object.get(comp, "is_compost_barn", false)

supplement_failed("no_windrows") if count(windrows) == 0

supplement_failed("windrow_noncompliant") if {
	some _, v in windrow_violations
	count(v) > 0
}

# O6_21-COMP-07: Ausbringung des Komposts bzw. Abgabe an Dritte dokumentieren.
supplement_failed("application_or_transfer_not_documented") if {
	not comp.documented_application_or_transfer
}

supplement_violations := {code | some code in supplement_codes; supplement_failed(code)}

supplement_compliant if {
	application.supplement_valid
	count(supplement_violations) == 0
}

# Stalldefinition, Liegebereich, Einstreu, Platzbedarf und Gruppenhaltung (o6_21, Kapitel 5 und 6.3).
package oepul.o6_21.housing

import data.oepul.o6_21.lib

compartments := object.get(input, ["livestock", "stall_compartments"], [])

animals := object.get(input, ["livestock", "cattle_animals"], [])

# Belegung zum Prüfstichtag: alle am Betrieb befindlichen Tiere des Abteils, auch wenn sie sich z. B. auf der Weide befinden.
compartment_animals(cid) := [a |
	some a in animals
	object.get(a, "stall_compartment_id", null) == cid
	present_at(a, lib.assessment_date)
]

present_at(a, d) if {
	lib.parse_date(a.on_farm_from) <= lib.parse_date(d)
	not is_string(object.get(a, "on_farm_until", null))
}

present_at(a, d) if {
	lib.parse_date(a.on_farm_from) <= lib.parse_date(d)
	lib.parse_date(a.on_farm_until) >= lib.parse_date(d)
}

# --- Stalldefinition (Kapitel 5) -------------------------------------------------------------

# O6_21-DEF-01: Stall = befestigtes Gebäude, mind. dreiseitige Verschalung/Windfangnetze, überdachte
# Liegeplätze, befestigter Boden (Schotter/Lehm gelten nicht als befestigt), Sammelbehälter für flüssigen Kot/Harn.
standard_stall_ok(b) if {
	b.is_fixed_building
	b.enclosed_sides_count >= 3
	b.lying_area_roofed
	b.floor_material in lib.tables.paved_floor_materials
	liquid_collection_ok(b)
}

liquid_collection_ok(b) if not b.liquid_excreta_occur

liquid_collection_ok(b) if {
	b.liquid_excreta_occur
	b.liquid_excreta_collectable
}

# O6_21-DEF-02: Offenstall – festes Dach über Liegeflächen, flüssigkeitsdichte Stallflächen,
# Abfluss der Sickerwässer in eine Sammelgrube.
open_stall_ok(b) if {
	b.is_open_stall_system
	b.solid_roof_over_lying_area
	b.surfaces_liquid_tight
	b.seepage_drain_to_collection_pit
}

building_ok(c) if standard_stall_ok(c.building)

building_ok(c) if open_stall_ok(c.building)

# --- Platzbedarf (Kapitel 6.3.1) --------------------------------------------------------------

animal_total_area_requirement(a) := lib.tables.cow_space_requirement.total_area_m2_per_animal if {
	object.get(a, "is_cow", false)
}

animal_total_area_requirement(a) := lib.space_row_for_weight(a.current_weight_kg).total_area_m2_per_animal if {
	not object.get(a, "is_cow", false)
	is_number(object.get(a, "current_weight_kg", null))
}

animal_lying_area_requirement(a) := lib.tables.cow_space_requirement.lying_area_m2_per_animal if {
	object.get(a, "is_cow", false)
}

animal_lying_area_requirement(a) := lib.space_row_for_weight(a.current_weight_kg).lying_area_m2_per_animal if {
	not object.get(a, "is_cow", false)
	is_number(object.get(a, "current_weight_kg", null))
}

animals_missing_weight contains a.ear_tag if {
	some a in animals
	object.get(a, "stall_compartment_id", null) != null
	not object.get(a, "is_cow", false)
	not is_number(object.get(a, "current_weight_kg", null))
}

# O6_21-SPACE-01 / O6_21-SPACE-03: Mindestgesamtfläche für alle Tiere der Box (auch nicht förderfähige Tiere, Kühe mit 6,00 m²).
required_total_area(cid) := lib.r4(sum([animal_total_area_requirement(a) | some a in compartment_animals(cid)]))

# Summe der tabellarischen Liegeflächen je Tier (entspricht 40 % der Gesamtfläche).
table_lying_area(cid) := lib.r4(sum([animal_lying_area_requirement(a) | some a in compartment_animals(cid)]))

# O6_21-LIE-02: eingestreute Liegefläche mindestens 40 % der geforderten nutzbaren Gesamtfläche.
required_bedded_area(cid) := lib.r4(required_total_area(cid) * lib.thresholds.bedded_lying_area_min_share)

suckler_cubicle(c) if object.get(c, ["suckler_cubicle_housing", "applies"], false)

total_area_ok(c) if {
	not suckler_cubicle(c)
	lib.r4(c.usable_paved_area_m2) >= required_total_area(c.compartment_id)
}

# O6_21-SPACE-04: Mutterkuhbetriebe mit Liegeboxenlaufstall – Gesamtfläche gilt bei Einhaltung des Tierschutzgesetzes als erfüllt.
total_area_ok(c) if {
	suckler_cubicle(c)
	c.suckler_cubicle_housing.meets_animal_welfare_act_space
}

bedded_area_ok(c) if {
	not suckler_cubicle(c)
	lib.r4(c.bedded_lying_area_m2) >= required_bedded_area(c.compartment_id)
}

calf_creep_required_total_area(c) := lib.r4(sum([animal_total_area_requirement(a) |
	some a in compartment_animals(c.compartment_id)
	not object.get(a, "is_cow", false)
	lib.age_under_half_year_at(a, lib.assessment_date)
]))

# O6_21-SPACE-04: Liegeboxen für Tiere über 6 Monate, zusätzlicher Liegeplatz für Kälber,
# im Kälberschlupf eingestreute Liegefläche mindestens 40 % der geforderten Gesamtfläche.
bedded_area_ok(c) if {
	suckler_cubicle(c)
	s := c.suckler_cubicle_housing
	s.each_animal_over_6_months_has_legal_cubicle
	s.calves_have_additional_free_lying_place
	lib.r4(s.calf_creep_bedded_area_m2) >= lib.r4(calf_creep_required_total_area(c) * lib.thresholds.bedded_lying_area_min_share)
}

# --- Liegebereich und Einstreu (Kapitel 6.3.1) -----------------------------------------------

# O6_21-LIE-01: geschlossene (planbefestigte) Liegefläche, Perforationsanteil max. 5 %.
closed_lying_area_ok(c) if {
	c.lying_area_perforation_percent <= lib.thresholds.closed_lying_area_max_perforation_percent
}

# O6_21-LIE-03 / O6_21-LIE-04: weiche Liegefläche wird zur Sicherung der Trockenheit eingestreut;
# harter Gummi bzw. befestigte Fläche benötigt mind. 3 cm Einstreudecke.
bedding_ok(c) if {
	c.lying_surface_material == "soft_rubber_or_plastic"
	c.bedded_system
	c.bedding_soft_and_dry
}

bedding_ok(c) if {
	c.lying_surface_material in {"hard_rubber", "paved"}
	c.bedding_depth_cm >= lib.thresholds.min_bedding_depth_cm_hard_surface
	c.bedding_soft_and_dry
}

# --- Befund je Stallabteil ----------------------------------------------------------------------

compartment_violations[cid] := v if {
	some c in compartments
	cid := c.compartment_id
	v := {code | some code in all_codes; compartment_check_failed(c, code)}
}

all_codes := {
	"stall_definition_not_met",
	"usable_area_insufficient",
	"bedded_lying_area_insufficient",
	"lying_area_not_closed",
	"bedding_insufficient",
	"no_group_housing",
	"no_bedded_system",
	"partial_areas_closed_off",
	"usable_area_not_paved",
}

compartment_check_failed(c, "stall_definition_not_met") if not building_ok(c)

compartment_check_failed(c, "usable_area_insufficient") if not total_area_ok(c)

compartment_check_failed(c, "bedded_lying_area_insufficient") if not bedded_area_ok(c)

compartment_check_failed(c, "lying_area_not_closed") if not closed_lying_area_ok(c)

compartment_check_failed(c, "bedding_insufficient") if not bedding_ok(c)

# O6_21-GROUP-01: Haltung in Gruppen auf eingestreuten Systemen.
compartment_check_failed(c, "no_group_housing") if not c.group_housing

compartment_check_failed(c, "no_bedded_system") if not c.bedded_system

# O6_21-SPACE-02: Absperren von Teilflächen nur für Routinearbeiten zulässig.
compartment_check_failed(c, "partial_areas_closed_off") if {
	object.get(c, "partial_areas_closed_except_routine_work", false)
}

# O6_21-SPACE-02: nutzbare Gesamtfläche nur befestigte Flächen (betoniert oder perforiert) mit ständigem Zugang.
compartment_check_failed(c, "usable_area_not_paved") if {
	object.get(c, "usable_area_includes_unpaved_or_inaccessible", false)
}

noncompliant_compartments contains cid if {
	some cid, v in compartment_violations
	count(v) > 0
}

# --- Belegungsplan (Kapitel 6.3.2, bis Antragsjahr 2024) ---------------------------------------

# O6_21-PLAN-02: maximal mögliche Anzahl je Gewichtsklasse aus dem Mindestplatzbedarf.
max_occupancy(area) := {row.weight_class: n |
	some row in lib.tables.space_requirements
	n := floor((area / row.total_area_m2_per_animal) + 0.000001)
}

occupancy_plan[cid] := max_occupancy(c.usable_paved_area_m2) if {
	some c in compartments
	cid := c.compartment_id
}

# O6_21-PLAN-01: Stallskizze und Belegungsplan bis einschließlich Antragsjahr 2024; ab 2025 entfallen.
stall_sketch_required if lib.year <= lib.deadlines.stall_sketch_required_until_year

stall_sketch_missing if {
	stall_sketch_required
	not object.get(lib.measure_input, "stall_sketch_and_occupancy_plan_available", false)
}

